//! The fixed parts of a pptxgenjs package: the theme, the slide master, the slide layout, the notes master and
//! slide, `presProps`, `viewProps`, `tableStyles` and the root and fixed relationships. The texts are what
//! pptxgenjs's `makeXml*` functions write (for the one slide layout every presentation has); the pieces a
//! presentation changes (the theme's fonts, the master's and layout's `p:cSld`, the notes text and slide number)
//! are the gaps between them.

use super::slide::{Backdrop, Csld, SlideObject, csld_xml};
use super::{Layout, SlideNumber};

/// The fonts of the theme (`pres.theme`): the heading (major) and body (minor) latin faces.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct ThemeFonts {
    pub head_font_face: Option<String>,
    pub body_font_face: Option<String>,
}

/// `makeXmlTheme`.
pub(super) fn theme_xml(fonts: &ThemeFonts) -> String {
    let face = |face: &Option<String>, fallback: &str| match face.as_deref() {
        Some(face) if !face.is_empty() => format!("<a:latin typeface=\"{face}\"/>"),
        _ => fallback.to_owned(),
    };
    format!(
        "{THEME_BEFORE_MAJOR_LATIN}{}{THEME_BEFORE_MINOR_LATIN}{}{THEME_AFTER_MINOR_LATIN}",
        face(&fonts.head_font_face, THEME_DEFAULT_MAJOR_LATIN),
        face(&fonts.body_font_face, THEME_DEFAULT_MINOR_LATIN)
    )
}

/// The layout every master and layout is positioned in: the default 16:9 sheet, whatever the deck's own is
/// (pptxgenjs gives the master and the layout the layout object it holds at construction).
fn default_layout() -> Layout {
    Layout { name: "screen16x9".to_owned(), width: 9_144_000.0, height: 5_143_500.0 }
}

/// `makeXmlMaster`: the slide master; a slide number set on any slide of the deck is on the master too, as `null`.
pub(super) fn master_xml(slide_number: Option<&SlideNumber>) -> String {
    let objects: [SlideObject; 0] = [];
    let csld = csld_xml(&Csld {
        name: None,
        backdrop: Backdrop::Plain,
        objects: &objects,
        slide_number,
        slide_number_text: "null".to_owned(),
        layout: &default_layout(),
    });
    format!("{MASTER_BEFORE_CSLD}{csld}{MASTER_AFTER_CSLD}")
}

/// `makeXmlLayout`: the one slide layout, `DEFAULT`; it carries the deck's slide number as number 1000.
pub(super) fn layout_xml(slide_number: Option<&SlideNumber>) -> String {
    let objects: [SlideObject; 0] = [];
    let csld = csld_xml(&Csld {
        name: Some("DEFAULT"),
        backdrop: Backdrop::Theme,
        objects: &objects,
        slide_number,
        slide_number_text: "1000".to_owned(),
        layout: &default_layout(),
    });
    format!("{LAYOUT_BEFORE_CSLD}{csld}{LAYOUT_AFTER_CSLD}")
}

/// `makeXmlNotesSlide`: `text` is the escaped notes text.
pub(super) fn notes_slide_xml(text: &str, slide_number: usize) -> String {
    format!("{NOTES_SLIDE_BEFORE_TEXT}{text}{NOTES_SLIDE_BEFORE_NUMBER}{slide_number}{NOTES_SLIDE_AFTER_NUMBER}")
}

/// `makeXmlNotesSlideRel`.
pub(super) fn notes_slide_rels_xml(slide_number: usize) -> String {
    format!("{NOTES_SLIDE_RELS_BEFORE_NUMBER}{slide_number}{NOTES_SLIDE_RELS_AFTER_NUMBER}")
}

